const DEFAULT_PORTS = { http: '80', ws: '80', https: '443', wss: '443', ftp: '21' }

export class UriError extends Error {}

export function parse(s) {
  const m = /^(?:([^:/?#]+):)?(?:\/\/([^/?#]*))?([^?#]*)(?:\?([^#]*))?(?:#([\s\S]*))?$/.exec(s)
  const [, scheme, authority, path, query, fragment] = m
  return { scheme, authority, path, query, fragment }
}

function splitAuthority(a) {
  let userinfo
  let rest = a
  const at = a.lastIndexOf('@')
  if (at >= 0) { userinfo = a.slice(0, at); rest = a.slice(at + 1) }
  const from = rest.lastIndexOf(']') + 1
  const c = rest.indexOf(':', from)
  if (c < 0) return { userinfo, host: rest, port: undefined }
  return { userinfo, host: rest.slice(0, c), port: rest.slice(c + 1) }
}

function normPct(s) {
  return s.replace(/%([0-9a-fA-F]{2})/g, (_, h) => {
    const ch = String.fromCharCode(parseInt(h, 16))
    return /[A-Za-z0-9\-._~]/.test(ch) ? ch : '%' + h.toUpperCase()
  })
}

function checkPct(s, name, line) {
  if (s !== undefined && /%(?![0-9a-fA-F]{2})/.test(s)) {
    throw new UriError(`error: line ${line}: the ${name} has a truncated percent-encoding`)
  }
}

const lowerAscii = (s) => s.replace(/[A-Z]/g, (c) => c.toLowerCase())

export function removeDots(path) {
  let input = path
  let out = ''
  while (input.length) {
    if (input.startsWith('../')) input = input.slice(3)
    else if (input.startsWith('./')) input = input.slice(2)
    else if (input.startsWith('/./')) input = input.slice(2)
    else if (input === '/.') input = '/'
    else if (input.startsWith('/../') || input === '/..') {
      input = input === '/..' ? '/' : input.slice(3)
      out = out.slice(0, Math.max(out.lastIndexOf('/'), 0))
    } else if (input === '.' || input === '..') input = ''
    else {
      const i = input.indexOf('/', 1)
      const seg = i < 0 ? input : input.slice(0, i)
      out += seg
      input = input.slice(seg.length)
    }
  }
  return out
}

function serialize(c) {
  let r = ''
  if (c.scheme !== undefined) r += c.scheme + ':'
  if (c.authority !== undefined) r += '//' + c.authority
  r += c.path
  if (c.query !== undefined) r += '?' + c.query
  if (c.fragment !== undefined) r += '#' + c.fragment
  return r
}

export function normalize(c, line) {
  let auth = c.authority !== undefined ? splitAuthority(c.authority) : undefined
  checkPct(c.path, 'path', line)
  if (auth) {
    checkPct(auth.userinfo, 'userinfo', line)
    checkPct(auth.host, 'host', line)
  }
  checkPct(c.query, 'query', line)
  checkPct(c.fragment, 'fragment', line)

  const scheme = c.scheme === undefined ? undefined : lowerAscii(c.scheme)
  const out = { scheme }
  if (auth) {
    let a = ''
    if (auth.userinfo !== undefined) a += normPct(auth.userinfo) + '@'
    a += lowerAscii(normPct(auth.host))
    const def = scheme !== undefined ? DEFAULT_PORTS[scheme] : undefined
    if (auth.port !== undefined && auth.port !== '' && auth.port !== def) a += ':' + auth.port
    out.authority = a
  }
  let path = removeDots(normPct(c.path))
  if (out.authority !== undefined && path === '') path = '/'
  out.path = path
  out.query = c.query === undefined ? undefined : normPct(c.query)
  out.fragment = c.fragment === undefined ? undefined : normPct(c.fragment)
  return serialize(out)
}

export function resolve(base, ref) {
  const t = {}
  if (ref.scheme !== undefined) {
    Object.assign(t, ref, { path: removeDots(ref.path) })
  } else if (ref.authority !== undefined) {
    Object.assign(t, ref, { scheme: base.scheme, path: removeDots(ref.path) })
  } else {
    t.scheme = base.scheme
    t.authority = base.authority
    t.fragment = ref.fragment
    if (ref.path === '') {
      t.path = base.path
      t.query = ref.query !== undefined ? ref.query : base.query
    } else {
      if (ref.path.startsWith('/')) t.path = removeDots(ref.path)
      else {
        let merged
        if (base.authority !== undefined && base.path === '') merged = '/' + ref.path
        else {
          const i = base.path.lastIndexOf('/')
          merged = i < 0 ? ref.path : base.path.slice(0, i + 1) + ref.path
        }
        t.path = removeDots(merged)
      }
      t.query = ref.query
    }
  }
  return t
}
