#!/usr/bin/env node
/**
 * The command. `node src/cli.js normalize` normalizes one URI reference per
 * input line; `node src/cli.js resolve` resolves the reference on each line
 * against the base that precedes it. Both print one result per line.
 */
import { readFileSync } from 'node:fs'
import { parse, normalize, resolve, UriError } from './uri.js'

const mode = process.argv[2]
if (process.argv.length !== 3 || (mode !== 'normalize' && mode !== 'resolve')) {
  process.stderr.write('error: usage: cli.js normalize|resolve\n')
  process.exit(2)
}

const lines = readFileSync(0, 'utf8').split('\n')
if (lines[lines.length - 1] === '') lines.pop()

try {
  const out = lines.map((rec, i) => {
    const n = i + 1
    if (mode === 'normalize') return normalize(parse(rec), n)
    const sp = rec.indexOf(' ')
    if (sp < 0) throw new UriError(`error: line ${n}: expected a base and a reference`)
    const base = parse(rec.slice(0, sp))
    if (base.scheme === undefined) throw new UriError(`error: line ${n}: the base has no scheme`)
    return normalize(resolve(base, parse(rec.slice(sp + 1))), n)
  })
  if (out.length) process.stdout.write(out.join('\n') + '\n')
} catch (e) {
  if (!(e instanceof UriError)) throw e
  process.stderr.write(e.message + '\n')
  process.exit(2)
}
