const newTable = () => ({ type: 'table', entries: new Map(), made: false })
const BARE = /[A-Za-z0-9_-]/
const INT = /^[+-]?\d+(?:_\d+)*$/
const FLOAT = /^[+-]?\d+(?:_\d+)*(?:\.\d+(?:_\d+)*)?(?:[eE][+-]?\d+(?:_\d+)*)?$/

