    this.ws()
    const parts = [this.name()]
    for (;;) {
      const save = this.i
      this.ws()
      if (this.s[this.i] !== '.') {
        this.i = save
        return parts
      }
      this.i++
      this.ws()
      parts.push(this.name())
    }
  }

