      if (this.peek() === '#') fail('expected a value')
      items.push(this.value(prefix))
      if (this.atEnd()) fail('unterminated array')
      const c = this.peek()
      if (c === ',') this.i++
      else if (c === ']') {
        this.i++
        return { type: 'array', items, aot: false }
      } else fail('unterminated array')
    }
  }

  inline(prefix) {
    this.i++
    const table = newTable()
    if (this.atEnd()) fail('unterminated inline table')
    if (this.peek() === '}') {
      this.i++
      return table
    }
    for (;;) {
      if (this.atEnd()) fail('unterminated inline table')
      const key = this.dotted()
      this.ws()
      if (this.peek() !== '=') fail('expected = in an inline table')
      this.i++
      assign(table, prefix, key, () => this.value(prefix.concat(key)), this)
      if (this.atEnd()) fail('unterminated inline table')
      const c = this.peek()
      this.i++
      if (c === '}') return table
      if (c !== ',') fail('unterminated inline table')
    }
  }
}

// Walks `path` below `table`, creating missing tables; returns the table reached.
function walk(table, base, path) {
  const here = base.slice()
  for (const k of path) {
    here.push(k)
    let next = table.entries.get(k)
    if (next === undefined) {
      next = newTable()
      table.entries.set(k, next)
    } else if (next.type === 'array' && next.aot) {
      next = next.items[next.items.length - 1]
    } else if (next.type !== 'table') fail(`${here.join('.')} is not a table`)
    table = next
  }
  return table
}

function assign(table, base, key, getValue, line) {
  const parent = walk(table, base, key.slice(0, -1))
  const last = key[key.length - 1]
  // The value is parsed before the duplicate check, so value errors win.
  const v = getValue()
  if (parent.entries.has(last)) fail(`key ${base.concat(key).join('.')} is defined twice`)
  parent.entries.set(last, v)
}

function header(root, line) {
  line.i++
  const aot = line.peek() === '['
  if (aot) line.i++
  const path = line.dotted()
  line.ws()
  if (line.peek() !== ']') fail('unterminated table header')
  line.i++
  if (aot) {
    if (line.peek() !== ']') fail('unterminated table header')
    line.i++
  }
  if (!line.atEnd()) fail('trailing text after a table header')
  const full = path.join('.')
  const parent = walk(root, [], path.slice(0, -1))
  const last = path[path.length - 1]
  const cur = parent.entries.get(last)
  if (aot) {
    let arr = cur
    if (arr === undefined) {
      arr = { type: 'array', items: [], aot: true }
      parent.entries.set(last, arr)
    } else if (arr.type !== 'array' || !arr.aot) fail(`${full} is not an array of tables`)
    const t = newTable()
    t.made = true
    arr.items.push(t)
    return { table: t, path }
  }
  if (cur === undefined) {
    const t = newTable()
    t.made = true
    parent.entries.set(last, t)
    return { table: t, path }
  }
  if (cur.type !== 'table') fail(`${full} is not a table`)
  if (cur.made) fail(`table ${full} is defined twice`)
  cur.made = true
  return { table: cur, path }
}

export function parseDocument(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const root = newTable()
  let cur = { table: root, path: [] }
  for (let n = 0; n < lines.length; n++) {
    try {
      const line = new Line(lines[n])
      if (line.atEnd()) continue
      if (line.peek() === '[') {
        cur = header(root, line)
        continue
      }
      const key = line.dotted()
      line.ws()
      if (line.peek() !== '=') fail('expected key = value')
      line.i++
      assign(cur.table, cur.path, key, () => line.value(cur.path.concat(key)), line)
      if (!line.atEnd()) fail('trailing text after a value')
    } catch (e) {
      if (e instanceof ParseError) e.line = n + 1
      throw e
    }
  }
  return root
}
"}

