const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])
const PUNCT2 = new Set(['==', '!=', '<=', '>=', '&&', '||', '->', '=>'])
const PUNCT1 = new Set('+-*/%=<>!(){}[],;.'.split(''))
export const KINDS = ['ident', 'keyword', 'number', 'punct', 'rawstring', 'string']

export class ScanError extends Error {
  constructor(line, col, reason) {
    super(`${line}:${col}: ${reason}`)
  }
}

const isLetter = (c) => c !== undefined && /^[A-Za-z_]$/.test(c)
const isDigit = (c) => c !== undefined && c >= '0' && c <= '9'
const isIdent = (c) => isLetter(c) || isDigit(c)
const isHex = (c) => c !== undefined && /^[0-9a-fA-F]$/.test(c)

export function scan(text) {
  const s = Array.from(text)
  const n = s.length
  const tokens = []
  let i = 0, line = 1, col = 1
  const adv = (k = 1) => {
    for (let j = 0; j < k; j++) {
      const c = s[i++]
      if (c === '\n') { line++; col = 1 }
      else if (c === '\t') col = Math.floor((col - 1) / 4) * 4 + 5
      else col++
    }
  }
  // returns end index of a digit run starting at p (p must be at a digit)
  const run = (p, ok) => {
    while (p < n) {
      if (ok(s[p])) p++
      else if (s[p] === '_' && p > 0 && ok(s[p - 1]) && ok(s[p + 1])) p++
      else break
    }
    return p
  }
  while (i < n) {
    const c = s[i]
    if (c === ' ' || c === '\t' || c === '\r' || c === '\n') { adv(); continue }
    if (c === '/' && s[i + 1] === '/') {
      while (i < n && s[i] !== '\n') adv()
      continue
    }
    if (c === '/' && s[i + 1] === '*') {
      const l0 = line, c0 = col
      let depth = 0
      while (true) {
        if (i >= n) throw new ScanError(l0, c0, 'unterminated block comment')
        if (s[i] === '/' && s[i + 1] === '*') { depth++; adv(2) }
        else if (s[i] === '*' && s[i + 1] === '/') { depth--; adv(2); if (depth === 0) break }
        else adv()
      }
      continue
    }
    const l0 = line, c0 = col
    if (c === 'r' && s[i + 1] === '"') {
      let p = i + 2
      while (p < n && s[p] !== '"') p++
      if (p >= n) throw new ScanError(l0, c0, 'unterminated string')
      tokens.push({ line: l0, col: c0, kind: 'rawstring', body: JSON.stringify(s.slice(i + 2, p).join('')) })
      adv(p + 1 - i)
      continue
    }
    if (isLetter(c)) {
      let p = i
      while (isIdent(s[p])) p++
      const w = s.slice(i, p).join('')
      tokens.push({ line: l0, col: c0, kind: KEYWORDS.has(w) ? 'keyword' : 'ident', body: w })
      adv(p - i)
      continue
    }
    if (isDigit(c)) {
      let p = i
      let ok = isDigit
      let prefixed = false
      const x = s[i + 1]
      if (c === '0' && x !== undefined && /^[xXbBoO]$/.test(x)) {
        prefixed = true
        const lx = x.toLowerCase()
        ok = lx === 'x' ? isHex : lx === 'b' ? (d) => d === '0' || d === '1' : (d) => d >= '0' && d <= '7' && d.length === 1
        p = i + 2
        if (ok(s[p])) p = run(p, ok)
        else {
          while (isIdent(s[p])) p++
          throw new ScanError(l0, c0, `invalid number ${s.slice(i, p).join('')}`)
        }
      } else {
        p = run(p, isDigit)
        if (s[p] === '.' && isDigit(s[p + 1])) p = run(p + 1, isDigit)
        if (s[p] === 'e' || s[p] === 'E') {
          if (isDigit(s[p + 1])) p = run(p + 1, isDigit)
          else if ((s[p + 1] === '+' || s[p + 1] === '-') && isDigit(s[p + 2])) p = run(p + 2, isDigit)
        }
      }
      if (isIdent(s[p])) {
        while (isIdent(s[p])) p++
        throw new ScanError(l0, c0, `invalid number ${s.slice(i, p).join('')}`)
      }
      tokens.push({ line: l0, col: c0, kind: 'number', body: s.slice(i, p).join('') })
      adv(p - i)
      continue
    }
    if (c === '"') {
      let p = i + 1
      let out = ''
      let l = line, cc = col + 1
      const step = (ch) => { if (ch === '\t') cc = Math.floor((cc - 1) / 4) * 4 + 5; else cc++ }
      while (true) {
        if (p >= n) throw new ScanError(l0, c0, 'unterminated string')
        const ch = s[p]
        if (ch === '"') { p++; break }
        if (ch === '\n') throw new ScanError(l, cc, 'newline in string')
        if (ch === '\\') {
          const bl = l, bc = cc
          const e = s[p + 1]
          if (e === undefined) throw new ScanError(l0, c0, 'unterminated string')
          const simple = { n: '\n', t: '\t', r: '\r', '\\': '\\', '"': '"', 0: '\0' }
          if (Object.hasOwn(simple, e)) { out += simple[e]; step(ch); step(e); p += 2; continue }
          if (e === 'x' && isHex(s[p + 2]) && isHex(s[p + 3])) {
            out += String.fromCharCode(parseInt(s[p + 2] + s[p + 3], 16))
            for (let k = 0; k < 4; k++) step('x'); p += 4; continue
          }
          if (e === 'u' && s[p + 2] === '{') {
            let q = p + 3
            while (isHex(s[q])) q++
            if (q > p + 3 && s[q] === '}') {
              const v = parseInt(s.slice(p + 3, q).join(''), 16)
              if (v <= 0x10ffff) {
                out += String.fromCodePoint(v)
                for (let k = p; k <= q; k++) step('u')
                p = q + 1
                continue
              }
            }
          }
          throw new ScanError(bl, bc, `invalid escape \\${e}`)
        }
        out += ch; step(ch); p++
      }
      tokens.push({ line: l0, col: c0, kind: 'string', body: JSON.stringify(out) })
      adv(p - i)
      continue
    }
    const two = c + (s[i + 1] ?? '')
    if (PUNCT2.has(two)) {
      tokens.push({ line: l0, col: c0, kind: 'punct', body: two })
      adv(2)
      continue
    }
    if (PUNCT1.has(c)) {
      tokens.push({ line: l0, col: c0, kind: 'punct', body: c })
      adv()
      continue
    }
    throw new ScanError(l0, c0, `unexpected character ${c}`)
  }
  return tokens
}
