import { readFileSync } from 'node:fs'

const DEFAULT_PORTS = { http: '80', ws: '80', https: '443', wss: '443', ftp: '21' }

function parse(s) {
  const r = { scheme: null, authority: null, path: '', query: null, fragment: null }
  let m = /^([^:/?#]+):/.exec(s)
  if (m) { r.scheme = m[1]; s = s.slice(m[0].length) }
  if (s.startsWith('//')) {
    const e = s.slice(2).search(/[/?#]/)
    const end = e < 0 ? s.length : e + 2
    r.authority = s.slice(2, end)
    s = s.slice(end)
  }
  const h = s.indexOf('#')
  if (h >= 0) { r.fragment = s.slice(h + 1); s = s.slice(0, h) }
  const q = s.indexOf('?')
  if (q >= 0) { r.query = s.slice(q + 1); s = s.slice(0, q) }
  r.path = s
  return r
}

function splitAuthority(a) {
  const at = a.lastIndexOf('@')
  const userinfo = at >= 0 ? a.slice(0, at) : null
  const hp = a.slice(at + 1)
  const colon = hp.indexOf(':', hp.lastIndexOf(']') + 1)
  // lastIndexOf(']') is -1 when absent, so the search starts at 0
  if (colon >= 0) return { userinfo, host: hp.slice(0, colon), port: hp.slice(colon + 1) }
  return { userinfo, host: hp, port: null }
}

function removeDots(path) {
  let inp = path
  const out = []
  while (inp.length) {
    if (inp.startsWith('../')) inp = inp.slice(3)
    else if (inp.startsWith('./')) inp = inp.slice(2)
    else if (inp.startsWith('/./')) inp = inp.slice(2)
    else if (inp === '/.') inp = '/'
    else if (inp.startsWith('/../') || inp === '/..') {
      inp = inp === '/..' ? '/' : inp.slice(3)
      out.pop()
    } else if (inp === '.' || inp === '..') inp = ''
    else {
      const i = inp.indexOf('/', 1)
      const seg = i < 0 ? inp : inp.slice(0, i)
      out.push(seg)
      inp = inp.slice(seg.length)
    }
  }
  return out.join('')
}

const UNRESERVED = /^[A-Za-z0-9\-._~]$/
function pct(s) {
  return s.replace(/%([0-9A-Fa-f]{2})/g, (_, h) => {
    const c = String.fromCharCode(parseInt(h, 16))
    return UNRESERVED.test(c) ? c : '%' + h.toUpperCase()
  })
}
const bad = (s) => s !== null && /%(?![0-9A-Fa-f]{2})/.test(s)
const lower = (s) => s.replace(/[A-Z]/g, (c) => c.toLowerCase())

class Fail extends Error {}

function normalize(r) {
  let parts = null
  if (r.authority !== null) parts = splitAuthority(r.authority)
  const checks = [
    ['path', r.path], ['userinfo', parts && parts.userinfo], ['host', parts && parts.host],
    ['query', r.query], ['fragment', r.fragment],
  ]
  for (const [name, v] of checks) if (bad(v)) throw new Fail(`the ${name} has a truncated percent-encoding`)
  const scheme = r.scheme === null ? null : lower(r.scheme)
  let out = scheme === null ? '' : scheme + ':'
  let path = pct(r.path)
