  const t = { scheme: base.scheme, authority: null, path: '', query: null, fragment: ref.fragment }
  if (ref.scheme !== null) {
    return { ...ref, path: removeDots(ref.path) }
  }
  if (ref.authority !== null) {
    return { ...ref, scheme: base.scheme, path: removeDots(ref.path) }
  }
  t.authority = base.authority
  if (ref.path === '') {
    t.path = base.path
    t.query = ref.query !== null ? ref.query : base.query
  } else {
    if (ref.path.startsWith('/')) t.path = removeDots(ref.path)
    else {
      let merged
      if (base.authority !== null && base.path === '') merged = '/' + ref.path
      else {
        const i = base.path.lastIndexOf('/')
        merged = i < 0 ? ref.path : base.path.slice(0, i + 1) + ref.path
      }
      t.path = removeDots(merged)
    }
    t.query = ref.query
  }
  return t
}

function main() {
  const mode = process.argv[2]
  if (process.argv.length !== 3 || (mode !== 'normalize' && mode !== 'resolve')) {
    process.stderr.write('error: usage: cli.js normalize|resolve\n')
    process.exit(2)
  }
  const lines = readFileSync(0, 'utf8').split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const results = []
  for (let n = 1; n <= lines.length; n++) {
    const line = lines[n - 1]
    try {
      if (mode === 'normalize') results.push(normalize(parse(line)))
      else {
        const sp = line.indexOf(' ')
        if (sp < 0) throw new Fail('expected a base and a reference')
        const base = parse(line.slice(0, sp))
        if (base.scheme === null) throw new Fail('the base has no scheme')
        results.push(normalize(resolve(base, parse(line.slice(sp + 1)))))
      }
    } catch (e) {
      if (!(e instanceof Fail)) throw e
      process.stderr.write(`error: line ${n}: ${e.message}\n`)
      process.exit(2)
    }
  }
  process.stdout.write(results.map((x) => x + '\n').join(''))
}

