  const n = i + 1
  const line = raw.trim()
  if (line === '' || line.startsWith('#')) return
  const t = line.split(/\s+/)
  const e = (m) => fail(`error: line ${n}: ${m}`)
  if (t[0] === 'candidates') {
    if (cands !== null || ballots.length) e('candidates must be declared once, before any ballot')
    if (t.length < 2) e('expected candidates <name>...')
    cands = []
    for (const nm of t.slice(1)) {
      if (!NAME.test(nm)) e(`invalid candidate name ${nm}`)
      if (set.has(nm)) e(`candidate ${nm} is declared twice`)
      set.add(nm); cands.push(nm)
    }
  } else if (t[0] === 'ballot') {
    if (cands === null) e('candidates must be declared once, before any ballot')
    if (t.length < 3) e('expected ballot <count> <candidate>...')
    if (!/^[1-9][0-9]*$/.test(t[1])) e('count must be a positive integer')
    const seen = new Set()
    for (const nm of t.slice(2)) {
      if (!set.has(nm)) e(`unknown candidate ${nm}`)
      if (seen.has(nm)) e(`candidate ${nm} is repeated`)
      seen.add(nm)
    }
    ballots.push([BigInt(t[1]), t.slice(2)])
  } else e(`unknown directive ${t[0]}`)
})
if (cands === null) fail('error: no candidates')

const cont = new Set(cands)
const hist = []
const out = []
let winner = null
for (;;) {
  const c = new Map([...cont].map((x) => [x, 0n]))
  let active = 0n, total = 0n
  for (const [k, l] of ballots) {
    total += k
    const f = l.find((x) => cont.has(x))
    if (f !== undefined) { c.set(f, c.get(f) + k); active += k }
  }
  hist.push(c)
  const order = [...cont].sort((a, b) => (c.get(a) > c.get(b) ? -1 : c.get(a) < c.get(b) ? 1 : a < b ? -1 : a > b ? 1 : 0))
  let line = `round ${hist.length}: ` + order.map((x) => `${x}=${c.get(x)}`).join(' ') + ` exhausted=${total - active}`
  out.push(line)
  if (active === 0n) break
  const top = order[0]
  if (c.get(top) * 2n > active) { winner = top; break }
  let min = c.get(order[order.length - 1])
  let T = order.filter((x) => c.get(x) === min)
  for (let r = 0; T.length > 1 && r < hist.length; r++) {
    const vs = T.map((x) => hist[r].get(x))
    const m = vs.reduce((a, b) => (a < b ? a : b))
    if (vs.some((v) => v !== m)) { T = T.filter((x) => hist[r].get(x) === m); r = -1 }
  }
  const el = T.length === 1 ? T[0] : T.sort()[T.length - 1]
  cont.delete(el)
  out.push(`eliminated ${el}`)
}
const end = winner ? `winner ${winner}` : 'no winner'
if (mode === 'rounds') process.stdout.write(out.join('\n') + '\n' + end + '\n')
else process.stdout.write(`rounds ${hist.length}\n${end}\n`)
EOF
