export class ParseError extends Error {}
const fail = (m) => { throw new ParseError(m) }

const newTable = () => ({ t: 'table', m: new Map(), hdr: false })
const isBare = (c) => c !== undefined && /[A-Za-z0-9_-]/.test(c)
const isWs = (c) => c === ' ' || c === '\t'
const isEnd = (c) => c === undefined || c === '#' || c === ';'

class Line {
  constructor(s) { this.s = s; this.i = 0 }
  get c() { return this.s[this.i] }
  ws() { while (isWs(this.c)) this.i++ }
}

function parseString(L) {
  const q = L.c
  L.i++
  let out = ''
  for (;;) {
    const c = L.c
    if (c === undefined) fail('unterminated string')
    L.i++
    if (c === q) return out
    if (q === "'" || c !== '\\') { out += c; continue }
    const e = L.c
    if (e === undefined) fail('unterminated string')
    L.i++
    if (e === '"') out += '"'
    else if (e === '\\') out += '\\'
    else if (e === 'n') out += '\n'
    else if (e === 't') out += '\t'
    else if (e === 'r') out += '\r'
    else if (e === '0') out += '\0'
    else if (e === 'u') {
      const h = L.s.substr(L.i, 4)
      if (!/^[0-9a-fA-F]{4}$/.test(h)) fail('invalid escape \\u')
      out += String.fromCharCode(parseInt(h, 16))
      L.i += 4
    } else {
      const cp = String.fromCodePoint(L.s.codePointAt(L.i - 1))
      fail('invalid escape \\' + cp)
    }
  }
}

function parseName(L) {
  const c = L.c
  if (c === '"' || c === "'") return parseString(L)
  if (!isBare(c)) fail('expected a name')
  const st = L.i
  while (isBare(L.c)) L.i++
  return L.s.slice(st, L.i)
