for (const w of order) {
  if (!deps.has(w[1])) deps.set(w[1], new Set())
  for (const x of w.slice(2)) deps.get(w[1]).add(x)
}
const names = [...cost.keys()].sort((a, b) => (a < b ? -1 : a > b ? 1 : 0))
const depList = new Map(names.map((k) => [k, [...(deps.get(k) || [])].sort((a, b) => (a < b ? -1 : a > b ? 1 : 0))]))

// cycle detection
{
  const state = new Map()
  const stack = []
  const visit = (u) => {
    state.set(u, 1)
    stack.push(u)
    for (const v of depList.get(u)) {
      if (state.get(v) === 1) {
        const cyc = stack.slice(stack.indexOf(v)).concat(v)
        fail('error: cycle: ' + cyc.join(' -> '), 3)
      }
      if (!state.has(v)) visit(v)
    }
    stack.pop()
    state.set(u, 2)
  }
