}

const start = new Map(), finish = new Map(), depth = new Map()
const topo = []
{
  const seen = new Set()
  const go = (u) => {
    if (seen.has(u)) return
    seen.add(u)
    for (const v of depList.get(u)) go(v)
    topo.push(u)
  }
  names.forEach(go)
}
