  let s = 0, d = 0
  for (const v of depList.get(u)) {
    s = Math.max(s, finish.get(v))
    d = Math.max(d, depth.get(v) + 1)
  }
  start.set(u, s); finish.set(u, s + cost.get(u)); depth.set(u, d)
  total = Math.max(total, s + cost.get(u))
}

let out = ''
if (mode === 'waves') {
  const waves = []
  for (const k of names) (waves[depth.get(k)] ||= []).push(k)
  waves.forEach((ws, i) => { out += `wave ${i}: ${ws.join(' ')}\n` })
  out += `total ${total}\n`
} else if (mode === 'explain') {
  for (const k of names) out += `${k} start=${start.get(k)} finish=${finish.get(k)} depth=${depth.get(k)}\n`
  out += `total ${total}\n`
} else {
  const prio = new Map()
  const dependents = new Map(names.map((k) => [k, []]))
  for (const k of names) for (const v of depList.get(k)) dependents.get(v).push(k)
  for (const u of [...topo].reverse()) {
    let m = 0
    for (const x of dependents.get(u)) m = Math.max(m, prio.get(x))
    prio.set(u, m + cost.get(u))
  }
  const fin = new Map()
  const free = new Array(workers).fill(0)
  const runs = Array.from({ length: workers }, () => [])
  const pending = new Set(names)
  let t = 0
  let makespan = 0
  while (pending.size) {
    for (;;) {
      let wi = free.findIndex((f) => f <= t)
      if (wi < 0) break
      let best = null
      for (const k of pending) {
        if (!depList.get(k).every((d) => fin.has(d) && fin.get(d) <= t)) continue
        if (best === null || prio.get(k) > prio.get(best) || (prio.get(k) === prio.get(best) && k < best)) best = k
      }
      if (best === null) break
      pending.delete(best)
      const f = t + cost.get(best)
      fin.set(best, f)
      free[wi] = f
      runs[wi].push(`${best}@${t}-${f}`)
      makespan = Math.max(makespan, f)
    }
    if (!pending.size) break
    let next = Infinity
    for (const f of free) if (f > t && f < next) next = f
    for (const f of fin.values()) if (f > t && f < next) next = f
    t = next
  }
  runs.forEach((r, i) => { out += `worker ${i}:${r.map((x) => ' ' + x).join('')}\n` })
  out += `makespan ${makespan}\n`
}
