  let pos = 0, k = 0
  while (k < all.length) {
    const start = all[k].bs
    let end = all[k].be
    const group = [all[k++]]
    while (k < all.length && all[k].bs <= end) {
      end = Math.max(end, all[k].be)
      group.push(all[k++])
    }
    if (start > pos) emit('stable', base.slice(pos, start))
    pos = end
    const baseLines = base.slice(start, end)
    const part = (side, src) => {
      const cs = group.filter(c => c.side === side)
      if (!cs.length) return baseLines
      const first = cs[0]
      const lastC = cs.reduce((a, c) => (c.be > a.be ? c : a), cs[0])
      const from = first.ss - (first.bs - start)
      const to = lastC.se + (end - lastC.be)
      return src.slice(from, to)
    }
    const m = part(0, mine), t = part(1, theirs)
    if (eq(m, t)) emit('both', m)
    else if (eq(m, baseLines)) emit('theirs', t)
    else if (eq(t, baseLines)) emit('mine', m)
