function changes(base, side) {
  const n = base.length, m = side.length
  const L = Array.from({ length: n + 1 }, () => new Int32Array(m + 1))
  for (let i = n - 1; i >= 0; i--) {
    for (let j = m - 1; j >= 0; j--) {
      L[i][j] = base[i] === side[j] ? L[i + 1][j + 1] + 1 : Math.max(L[i + 1][j], L[i][j + 1])
    }
  }
  const out = []
  let i = 0, j = 0, bi = 0, sj = 0
  const flush = (ei, ej) => {
    if (ei > bi || ej > sj) out.push({ bs: bi, be: ei, ss: sj, se: ej })
  }
  while (i < n && j < m) {
    if (base[i] === side[j]) {
      flush(i, j)
      i++; j++
      bi = i; sj = j
    } else if (L[i + 1][j] >= L[i][j + 1]) i++
    else j++
  }
  flush(n, m)
  return out
}

const eq = (a, b) => a.length === b.length && a.every((x, k) => x === b[k])

export function merge(mine, base, theirs, mode) {
  const all = [
    ...changes(base, mine).map(c => ({ ...c, side: 0 })),
    ...changes(base, theirs).map(c => ({ ...c, side: 1 })),
  ]
  all.sort((a, b) => a.bs - b.bs || a.side - b.side)
  const out = []
  let conflict = false
  const emit = (kind, lines, extra) => {
    if (mode === 'regions') out.push(extra ?? `${kind} ${lines.length}`)
    else out.push(...lines)
  }
  let pos = 0, k = 0
  while (k < all.length) {
    const start = all[k].bs
    let end = all[k].be
    const group = [all[k++]]
    while (k < all.length && all[k].bs <= end) {
      end = Math.max(end, all[k].be)
      group.push(all[k++])
    }
    if (start > pos) emit('stable', base.slice(pos, start))
    pos = end
    const baseLines = base.slice(start, end)
    const part = (side, src) => {
      const cs = group.filter(c => c.side === side)
      if (!cs.length) return baseLines
      const first = cs[0]
      const lastC = cs.reduce((a, c) => (c.be > a.be ? c : a), cs[0])
      const from = first.ss - (first.bs - start)
      const to = lastC.se + (end - lastC.be)
      return src.slice(from, to)
    }
    const m = part(0, mine), t = part(1, theirs)
    if (eq(m, t)) emit('both', m)
    else if (eq(m, baseLines)) emit('theirs', t)
    else if (eq(t, baseLines)) emit('mine', m)
    else {
      conflict = true
      if (mode === 'regions') out.push(`conflict mine=${m.length} base=${baseLines.length} theirs=${t.length}`)
      else {
        out.push('<<<<<<< mine', ...m)
        if (mode === 'merge') out.push('||||||| base', ...baseLines)
        out.push('=======', ...t, '>>>>>>> theirs')
      }
    }
  }
  if (pos < base.length) emit('stable', base.slice(pos))
  return { out, conflict }
}
