const ERR = (v) => ({ k: 'e', v })
const NUM = (v) => ({ k: 'n', v })

export function parseAddr(w) {
  const m = /^([A-Za-z]{1,2})([0-9]{1,3})$/.exec(w)
  if (!m) return null
  const row = Number(m[2])
  if (row < 1) return null
  const c = m[1].toUpperCase()
  const col = c.length === 1 ? c.charCodeAt(0) - 64 : 26 + (c.charCodeAt(0) - 65) * 26 + (c.charCodeAt(1) - 64)
  return { col, row, key: col + ',' + row, name: c + row }
}

function tokenize(s) {
  const t = []
  let i = 0
  while (i < s.length) {
    const c = s[i]
    if (c === ' ' || c === '\t') { i++; continue }
    let m
    if ((m = /^[0-9]+(\.[0-9]+)?/.exec(s.slice(i)))) { t.push({ t: 'num', v: Number(m[0]) }); i += m[0].length; continue }
    if ((m = /^[A-Za-z][A-Za-z0-9]*/.exec(s.slice(i)))) { t.push({ t: 'word', v: m[0] }); i += m[0].length; continue }
    if ((m = /^(<>|<=|>=|[<>=^*\/+\-(),:])/.exec(s.slice(i)))) { t.push({ t: 'op', v: m[0] }); i += m[0].length; continue }
    return null
  }
  return t
}

// returns AST or null
export function parseFormula(body) {
  const toks = tokenize(body)
  if (!toks) return null
  let p = 0
  const peek = () => toks[p]
  const isOp = (v) => toks[p] && toks[p].t === 'op' && toks[p].v === v
  const fail = () => { throw null }
  function cmp() {
    let l = add()
    while (peek() && peek().t === 'op' && ['=', '<>', '<', '<=', '>', '>='].includes(peek().v)) {
      const op = toks[p++].v
      l = { n: 'bin', op, l, r: add() }
    }
    return l
  }
  function add() {
    let l = mul()
    while (isOp('+') || isOp('-')) { const op = toks[p++].v; l = { n: 'bin', op, l, r: mul() } }
    return l
  }
  function mul() {
    let l = pow()
    while (isOp('*') || isOp('/')) { const op = toks[p++].v; l = { n: 'bin', op, l, r: pow() } }
    return l
  }
  function pow() {
    const l = unary()
    if (isOp('^')) { p++; return { n: 'bin', op: '^', l, r: pow() } }
    return l
  }
  function unary() {
    if (isOp('-') || isOp('+')) { const op = toks[p++].v; return { n: 'un', op, e: unary() } }
    return primary()
  }
  function primary() {
    const t = toks[p]
    if (!t) fail()
    if (t.t === 'num') { p++; return { n: 'num', v: t.v } }
    if (t.t === 'op' && t.v === '(') {
      p++
      const e = cmp()
      if (!isOp(')')) fail()
      p++
      return { n: 'paren', e }
    }
    if (t.t === 'word') {
      p++
      if (isOp('(')) {
        p++
        const args = []
        if (isOp(')')) { p++ } else {
          for (;;) {
            args.push(cmp())
            if (isOp(',')) { p++; continue }
            if (isOp(')')) { p++; break }
            fail()
          }
        }
        return { n: 'call', name: t.v.toUpperCase(), args }
      }
      if (isOp(':')) {
        p++
        const w = toks[p]
        if (!w || w.t !== 'word') fail()
        p++
        return { n: 'range', a: t.v, b: w.v }
      }
      const u = t.v.toUpperCase()
      if (u === 'TRUE') return { n: 'bool', v: true }
      if (u === 'FALSE') return { n: 'bool', v: false }
      return { n: 'ref', w: t.v }
    }
    fail()
  }
  let ast
  try {
    ast = cmp()
    if (p < toks.length) return null
  } catch (e) {
    if (e === null) return null
    throw e
  }
  return ast
}

function misplaced(a, direct = false) {
  switch (a.n) {
    case 'range': return !direct
    case 'bin': return misplaced(a.l) || misplaced(a.r)
    case 'un': case 'paren': return misplaced(a.e)
    case 'call': return a.args.some((x) => misplaced(x, true))
    default: return false
  }
}
export const hasMisplacedRange = (a) => misplaced(a)

export function rangeCells(a, b) {
  const x = parseAddr(a), y = parseAddr(b)
  if (!x || !y) return null
  const out = []
  for (let c = Math.min(x.col, y.col); c <= Math.max(x.col, y.col); c++)
    for (let r = Math.min(x.row, y.row); r <= Math.max(x.row, y.row); r++) out.push({ col: c, row: r, key: c + ',' + r })
  return out
}

export function collectDeps(a, out = new Map()) {
  switch (a.n) {
    case 'ref': { const x = parseAddr(a.w); if (x) out.set(x.key, x); break }
    case 'range': {
      const cs = rangeCells(a.a, a.b)
      if (cs) for (const c of cs) out.set(c.key, c)
      else for (const w of [a.a, a.b]) { const x = parseAddr(w); if (x) out.set(x.key, x) }
      break
    }
    case 'bin': collectDeps(a.l, out); collectDeps(a.r, out); break
    case 'un': case 'paren': collectDeps(a.e, out); break
    case 'call': a.args.forEach((x) => collectDeps(x, out)); break
  }
  return out
