          if (l.k !== r.k) c = rank[l.k] - rank[r.k]
          else if (l.k === 's') c = l.v === r.v ? 0 : cpLess(l.v, r.v) ? -1 : 1
          else c = l.k === 'b' ? Number(l.v) - Number(r.v) : l.v < r.v ? -1 : l.v > r.v ? 1 : 0
