import { readFileSync } from 'node:fs'
import { parseAddr, parseFormula, evaluate, collectDeps } from './formula.js'

const mode = process.argv.length === 3 ? process.argv[2] : null
function die(msg) { process.stderr.write(msg + '\n'); process.exit(2) }
if (mode !== 'values' && mode !== 'deps') die('error: usage: cli.js values|deps')

const lines = readFileSync(0, 'utf8').split('\n')
if (lines.length && lines[lines.length - 1] === '') lines.pop()

const cells = new Map()
lines.forEach((raw, i) => {
  const s = raw.replace(/^[ \t]+/, '')
  if (s === '' || s[0] === '#') return
  const m = /^[^ \t]*/.exec(s)[0]
  const content = s.slice(m.length).replace(/^[ \t]+/, '')
  const a = parseAddr(m)
  if (!a) die(`error: line ${i + 1}: invalid cell address ${m.toUpperCase()}`)
  if (cells.has(a.key)) die(`error: line ${i + 1}: cell ${a.name} is declared twice`)
  cells.set(a.key, { ...a, content })
})

const sorted = [...cells.values()].sort((x, y) => x.col - y.col || x.row - y.row)
const ERRS = ['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!']

function fmt(v) {
  if (v.k === 'e') return v.v
  if (v.k === 'b') return v.v ? 'TRUE' : 'FALSE'
  if (v.k === 's') return v.v
  return String(Number(v.v.toPrecision(10)))
}

const out = []
if (mode === 'deps') {
  for (const c of sorted) {
    let names = []
    if (c.content[0] === '=') {
      const ast = parseFormula(c.content.slice(1))
      if (ast) names = [...collectDeps(ast).values()].sort((x, y) => x.col - y.col || x.row - y.row).map((x) => x.name)
    }
    out.push(`${c.name}:` + names.map((n) => ' ' + n).join(''))
  }
} else {
  const cache = new Map()
  const busy = new Set()
  const get = (key) => {
    if (cache.has(key)) return cache.get(key)
    const c = cells.get(key)
    if (!c) return { k: 'n', v: 0 }
    if (busy.has(key)) return { k: 'e', v: '#CYCLE!' }
    busy.add(key)
    let v
    const t = c.content
    if (t[0] === '=') {
      const ast = parseFormula(t.slice(1))
      v = ast ? evaluate(ast, get) : { k: 'e', v: '#ERR!' }
    } else if (t === '') v = { k: 'n', v: 0 }
    else if (/^-?[0-9]+(\.[0-9]+)?$/.test(t)) v = { k: 'n', v: Number(t) }
    else if (ERRS.includes(t)) v = { k: 'e', v: t }
    else v = { k: 's', v: t }
    busy.delete(key)
    cache.set(key, v)
    return v
  }
  for (const c of sorted) out.push(`${c.name}=${fmt(get(c.key))}`)
}
if (out.length) process.stdout.write(out.join('\n') + '\n')
