    while (isOp('*') || isOp('/')) { const op = toks[p++].v; l = { n: 'bin', op, l, r: pow() } }
    return l
  }
  function pow() {
    const l = unary()
    if (isOp('^')) { p++; return { n: 'bin', op: '^', l, r: pow() } }
    return l
  }
  function unary() {
    if (isOp('-') || isOp('+')) { const op = toks[p++].v; return { n: 'un', op, e: unary() } }
    return primary()
  }
  function primary() {
    const t = toks[p]
    if (!t) fail()
    if (t.t === 'num') { p++; return { n: 'num', v: t.v } }
    if (t.t === 'op' && t.v === '(') {
      p++
      const e = cmp()
      if (!isOp(')')) fail()
      p++
      return { n: 'paren', e }
    }
    if (t.t === 'word') {
      p++
      if (isOp('(')) {
        p++
        const args = []
        if (isOp(')')) { p++ } else {
          for (;;) {
            args.push(cmp())
            if (isOp(',')) { p++; continue }
            if (isOp(')')) { p++; break }
            fail()
          }
        }
        return { n: 'call', name: t.v.toUpperCase(), args }
      }
      if (isOp(':')) {
        p++
        const w = toks[p]
        if (!w || w.t !== 'word') fail()
        p++
        return { n: 'range', a: t.v, b: w.v }
      }
      const u = t.v.toUpperCase()
      if (u === 'TRUE') return { n: 'bool', v: true }
      if (u === 'FALSE') return { n: 'bool', v: false }
      return { n: 'ref', w: t.v }
    }
    fail()
  }
  let ast
  try {
    ast = cmp()
    if (p < toks.length) return null
  } catch (e) {
    if (e === null) return null
    throw e
  }
  return ast
}

function misplaced(a, direct = false) {
  switch (a.n) {
    case 'range': return !direct
    case 'bin': return misplaced(a.l) || misplaced(a.r)
    case 'un': case 'paren': return misplaced(a.e)
    case 'call': return a.args.some((x) => misplaced(x, true))
    default: return false
  }
}
export const hasMisplacedRange = (a) => misplaced(a)

export function rangeCells(a, b) {
  const x = parseAddr(a), y = parseAddr(b)
  if (!x || !y) return null
  const out = []
  for (let c = Math.min(x.col, y.col); c <= Math.max(x.col, y.col); c++)
    for (let r = Math.min(x.row, y.row); r <= Math.max(x.row, y.row); r++) out.push({ col: c, row: r, key: c + ',' + r })
  return out
}

export function collectDeps(a, out = new Map()) {
  switch (a.n) {
    case 'ref': { const x = parseAddr(a.w); if (x) out.set(x.key, x); break }
    case 'range': {
      const cs = rangeCells(a.a, a.b)
      if (cs) for (const c of cs) out.set(c.key, c)
      else for (const w of [a.a, a.b]) { const x = parseAddr(w); if (x) out.set(x.key, x) }
      break
    }
    case 'bin': collectDeps(a.l, out); collectDeps(a.r, out); break
    case 'un': case 'paren': collectDeps(a.e, out); break
    case 'call': a.args.forEach((x) => collectDeps(x, out)); break
  }
  return out
}

const toNum = (x) => (x.k === 'n' ? x : x.k === 'b' ? NUM(x.v ? 1 : 0) : x.k === 's' ? ERR('#VALUE!') : x)
const fin = (v) => (Number.isFinite(v) ? NUM(v) : ERR('#DIV/0!'))
const rank = { n: 0, s: 1, b: 2 }

// getCell(key) -> value
export function evaluate(ast, getCell) {
  if (misplaced(ast)) return ERR('#ERR!')
  function expandArg(a) {
    if (a.n === 'range') {
      const cs = rangeCells(a.a, a.b)
      if (!cs) return [ERR('#REF!')]
      return cs.map((c) => getCell(c.key))
    }
    return [ev(a)]
  }
  function single(a) {
    const v = expandArg(a)
    return v.length === 1 ? v[0] : ERR('#ERR!')
  }
  function ev(a) {
    switch (a.n) {
      case 'num': return NUM(a.v)
      case 'bool': return { k: 'b', v: a.v }
      case 'paren': return ev(a.e)
      case 'ref': { const x = parseAddr(a.w); return x ? getCell(x.key) : ERR('#REF!') }
      case 'range': return ERR('#ERR!')
      case 'un': {
        const v = toNum(ev(a.e))
        if (v.k === 'e') return v
        return NUM(a.op === '-' ? -v.v : v.v)
      }
      case 'bin': {
        const l = ev(a.l)
        if (l.k === 'e') return l
        const r = ev(a.r)
        if (r.k === 'e') return r
        if (['=', '<>', '<', '<=', '>', '>='].includes(a.op)) {
          let c
          if (l.k !== r.k) c = rank[l.k] - rank[r.k]
          else if (l.k === 's') c = l.v === r.v ? 0 : cpLess(l.v, r.v) ? -1 : 1
          else c = l.k === 'b' ? Number(l.v) - Number(r.v) : l.v < r.v ? -1 : l.v > r.v ? 1 : 0
          const res = { '=': c === 0, '<>': c !== 0, '<': c < 0, '<=': c <= 0, '>': c > 0, '>=': c >= 0 }[a.op]
          return { k: 'b', v: res }
        }
        const ln = toNum(l); if (ln.k === 'e') return ln
        const rn = toNum(r); if (rn.k === 'e') return rn
        switch (a.op) {
          case '+': return fin(ln.v + rn.v)
          case '-': return fin(ln.v - rn.v)
          case '*': return fin(ln.v * rn.v)
          case '/': return rn.v === 0 ? ERR('#DIV/0!') : fin(ln.v / rn.v)
          case '^': return fin(Math.pow(ln.v, rn.v))
        }
        return ERR('#ERR!')
      }
      case 'call': return call(a)
    }
  }
  function call(a) {
    const n = a.name, args = a.args
    if (n === 'IF') {
      if (args.length !== 3) return ERR('#ERR!')
      const c = single(args[0])
      if (c.k === 'e') return c
      let t
      if (c.k === 'b') t = c.v
      else if (c.k === 'n') t = c.v !== 0
      else return ERR('#VALUE!')
      return single(args[t ? 1 : 2])
    }
    if (n === 'ABS') {
      if (args.length !== 1) return ERR('#ERR!')
