    const e = vals.find((v) => v.k === 'e')
    if (e) return e
    if (n === 'COUNT') return NUM(vals.filter((v) => v.k === 'n').length)
    const nums = []
    for (const v of vals) {
      const x = toNum(v)
      if (x.k === 'e') return x
      nums.push(x.v)
    }
    if (n === 'SUM') return fin(nums.reduce((s, x) => s + x, 0))
    if (n === 'AVG') return fin(nums.reduce((s, x) => s + x, 0) / nums.length)
    if (n === 'MIN') return fin(nums.reduce((s, x) => Math.min(s, x), Infinity))
    return fin(nums.reduce((s, x) => Math.max(s, x), -Infinity))
  }
