export function count({ candidates, ballots }, mode) {
  const continuing = new Set(candidates)
  const history = new Map(candidates.map((c) => [c, []]))
  const lines = []
  let k = 0
  let result
  for (;;) {
    k++
    const votes = new Map([...continuing].map((c) => [c, 0n]))
    let active = 0n
    let total = 0n
    for (const b of ballots) {
      total += b.count
      const c = b.prefs.find((p) => continuing.has(p))
      if (c !== undefined) { votes.set(c, votes.get(c) + b.count); active += b.count }
    }
    for (const [c, v] of votes) history.get(c).push(v)
    const order = [...votes.keys()].sort((a, b) =>
      votes.get(a) > votes.get(b) ? -1 : votes.get(a) < votes.get(b) ? 1 : a < b ? -1 : a > b ? 1 : 0)
    lines.push(`round ${k}: ${order.map((c) => `${c}=${votes.get(c)}`).join(' ')} exhausted=${total - active}`)
    if (active === 0n) { result = 'no winner'; break }
    const win = order.find((c) => votes.get(c) * 2n > active)
    if (win !== undefined) { result = `winner ${win}`; break }
    let min = null
    for (const v of votes.values()) if (min === null || v < min) min = v
    let tied = order.filter((c) => votes.get(c) === min)
    for (let r = 0; tied.length > 1 && r < k; r++) {
      let m = null
      for (const c of tied) { const v = history.get(c)[r]; if (m === null || v < m) m = v }
      tied = tied.filter((c) => history.get(c)[r] === m)
    }
    const out = tied.length === 1 ? tied[0] : tied.reduce((a, b) => (a > b ? a : b))
    continuing.delete(out)
    lines.push(`eliminated ${out}`)
  }
  if (mode === 'tally') return `rounds ${k}\n${result}\n`
  return lines.join('\n') + '\n' + result + '\n'
}
