import { readFileSync } from 'node:fs'
import { parseFormula } from './parse.js'
import { Sheet } from './eval.js'
import { addrKey, parseAddr } from './addr.js'

const mode = process.argv.length === 3 ? process.argv[2] : null
if (mode !== 'values' && mode !== 'deps') {
  process.stderr.write('error: usage: cli.js values|deps\n')
  process.exit(2)
}

const lines = readFileSync(0, 'utf8').split('\n')
if (lines.length && lines[lines.length - 1] === '') lines.pop()

const cells = new Map()
for (let i = 0; i < lines.length; i++) {
  const s = lines[i].replace(/^[ \t]+/, '')
  if (s === '' || s[0] === '#') continue
  const m = /^([^ \t]*)[ \t]*([\s\S]*)$/.exec(s)
  const raw = m[1]
  const a = parseAddr(raw)
  if (!a) {
    process.stderr.write(`error: line ${i + 1}: invalid cell address ${raw}\n`)
    process.exit(2)
  }
  const key = addrKey(a)
  if (cells.has(key)) {
    process.stderr.write(`error: line ${i + 1}: cell ${a.name} is declared twice\n`)
    process.exit(2)
  }
  cells.set(key, { addr: a, name: a.name, content: m[2] })
}

const list = [...cells.values()].sort((x, y) => x.addr.col - y.addr.col || x.addr.row - y.addr.row)
let out = ''
if (mode === 'values') {
  const sheet = new Sheet(cells)
  for (const c of list) out += `${c.name}=${sheet.format(sheet.get(c.addr))}\n`
} else {
  for (const c of list) {
    let names = []
    if (c.content[0] === '=') {
      const ast = parseFormula(c.content.slice(1))
      if (ast) {
        const set = new Map()
        collect(ast, set)
        names = [...set.values()].sort((x, y) => x.col - y.col || x.row - y.row)
      }
    }
    out += `${c.name}:${names.map((a) => ' ' + a.name).join('')}\n`
  }
}
process.stdout.write(out)

function collect(n, set) {
  if (n.k === 'ref') {
    const a = parseAddr(n.name)
    if (a) set.set(addrKey(a), a)
  } else if (n.k === 'range') {
    const a = parseAddr(n.a)
    const b = parseAddr(n.b)
    if (a && b) {
      for (let c = Math.min(a.col, b.col); c <= Math.max(a.col, b.col); c++)
        for (let r = Math.min(a.row, b.row); r <= Math.max(a.row, b.row); r++) {
          const x = { col: c, row: r, name: colName(c) + r }
          set.set(addrKey(x), x)
        }
    }
  } else if (n.k === 'call') for (const x of n.args) collect(x, set)
  else if (n.k === 'bin') { collect(n.l, set); collect(n.r, set) }
  else if (n.k === 'neg' || n.k === 'pos') collect(n.e, set)
}

function colName(c) {
  if (c <= 26) return String.fromCharCode(64 + c)
  const k = c - 27
  return String.fromCharCode(65 + Math.floor(k / 26)) + String.fromCharCode(65 + (k % 26))
}
"}

