{"command":"cat > src/cli.js <<'EOF'
import { readFileSync } from 'node:fs'

const mode = process.argv.length === 3 ? process.argv[2] : null
if (mode !== 'replay' && mode !== 'summary') {
  process.stderr.write('error: usage: cli.js replay|summary\n')
  process.exit(2)
}

const NAME = /^[A-Za-z0-9_.\/:-]+$/
const INT = /^(0|[1-9][0-9]*)$/

class Fail extends Error {}
const fail = (m) => { throw new Fail(m) }

function int(field, s, least) {
  if (!INT.test(s) || BigInt(s) < BigInt(least)) fail(`${field} must be an integer of at least ${least}`)
  return BigInt(s)
}

function run(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const policies = new Map()
  const routes = new Map()
  const states = new Map()
  const counts = new Map()
  const out = []
  let started = false
  let last = null
  let allowed = 0, denied = 0

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i].trim()
    if (line === '' || line[0] === '#') continue
    const t = line.split(/\s+/)
    try {
      const w = t[0]
      const decl = () => { if (started) fail('declarations must come before the first event') }
      if (w === 'bucket') {
        if (t.length !== 5) fail('expected bucket <name> <capacity> <refill> <per>')
        decl()
        if (!NAME.test(t[1])) fail(`invalid policy name ${t[1]}`)
        const capacity = int('capacity', t[2], 1)
        const refill = int('refill', t[3], 0)
        const per = int('per', t[4], 1)
        if (policies.has(t[1])) fail(`policy ${t[1]} is declared twice`)
        policies.set(t[1], { name: t[1], kind: 'bucket', capacity, refill, per })
      } else if (w === 'window') {
        if (t.length !== 4) fail('expected window <name> <limit> <span>')
        decl()
        if (!NAME.test(t[1])) fail(`invalid policy name ${t[1]}`)
        const limit = int('limit', t[2], 0)
        const span = int('span', t[3], 1)
        if (policies.has(t[1])) fail(`policy ${t[1]} is declared twice`)
        policies.set(t[1], { name: t[1], kind: 'window', limit, span })
      } else if (w === 'route') {
        if (t.length < 3) fail('expected route <prefix> <policy>...')
        decl()
        if (!NAME.test(t[1])) fail(`invalid route prefix ${t[1]}`)
        if (routes.has(t[1])) fail(`prefix ${t[1]} is routed twice`)
        const ps = t.slice(2).map((n) => policies.get(n) ?? fail(`unknown policy ${n}`))
        routes.set(t[1], ps)
      } else if (w === 'event') {
        if (t.length !== 3) fail('expected event <tick> <key>')
        const tick = int('tick', t[1], 0)
        const key = t[2]
        if (!NAME.test(key)) fail(`invalid key ${key}`)
        if (last !== null && tick < last) fail(`tick ${tick} is before tick ${last}`)
        started = true
        last = tick
        let best = null
        for (const p of routes.keys()) if (key.startsWith(p) && (best === null || p.length > best.length)) best = p
        let denier = null
        if (best !== null) {
          const sts = routes.get(best).map((p) => {
            const id = p.name + '\0' + key
            let s = states.get(id)
            if (!s) {
              s = p.kind === 'bucket' ? { units: p.capacity * p.per, at: tick } : { ticks: [] }
              states.set(id, s)
            }
            if (p.kind === 'bucket') {
              s.units += p.refill * (tick - s.at)
              s.at = tick
              if (s.units > p.capacity * p.per) s.units = p.capacity * p.per
            } else {
              s.ticks = s.ticks.filter((x) => x > tick - p.span)
            }
            return [p, s]
          })
          for (const [p, s] of sts) {
            const ok = p.kind === 'bucket' ? s.units >= p.per : BigInt(s.ticks.length) < p.limit
            if (!ok) { denier = p.name; break }
          }
          if (denier === null) {
            for (const [p, s] of sts) {
              if (p.kind === 'bucket') s.units -= p.per
              else s.ticks.push(tick)
            }
          }
        }
        const c = counts.get(key) ?? { a: 0, d: 0 }
        counts.set(key, c)
        if (denier === null) { c.a++; allowed++ } else { c.d++; denied++ }
        out.push(denier === null ? `${tick} ${key} allow` : `${tick} ${key} deny ${denier}`)
      } else {
        fail(`unknown directive ${w}`)
      }
    } catch (e) {
      if (e instanceof Fail) throw new Fail(`line ${i + 1}: ${e.message}`)
      throw e
    }
  }
  if (mode === 'summary') {
    const o = [...counts.keys()].sort((a, b) => (a < b ? -1 : a > b ? 1 : 0))
      .map((k) => `${k} allowed=${counts.get(k).a} denied=${counts.get(k).d}`)
    o.push(`total allowed=${allowed} denied=${denied}`)
    return o.join('\n') + '\n'
  }
  return out.length ? out.join('\n') + '\n' : ''
}

try {
  process.stdout.write(run(readFileSync(0, 'utf8')))
} catch (e) {
  if (!(e instanceof Fail)) throw e
  process.stderr.write(`error: ${e.message}\n`)
  process.exit(2)
}
EOF
