              s.units += p.refill * (tick - s.at)
              s.at = tick
              if (s.units > p.capacity * p.per) s.units = p.capacity * p.per
            } else {
              s.ticks = s.ticks.filter((x) => x > tick - p.span)
            }
            return [p, s]
          })
          for (const [p, s] of sts) {
            const ok = p.kind === 'bucket' ? s.units >= p.per : BigInt(s.ticks.length) < p.limit
            if (!ok) { denier = p.name; break }
          }
          if (denier === null) {
            for (const [p, s] of sts) {
              if (p.kind === 'bucket') s.units -= p.per
              else s.ticks.push(tick)
            }
          }
        }
        const c = counts.get(key) ?? { a: 0, d: 0 }
        counts.set(key, c)
        if (denier === null) { c.a++; allowed++ } else { c.d++; denied++ }
        out.push(denier === null ? `${tick} ${key} allow` : `${tick} ${key} deny ${denier}`)
      } else {
        fail(`unknown directive ${w}`)
      }
    } catch (e) {
      if (e instanceof Fail) throw new Fail(`line ${i + 1}: ${e.message}`)
      throw e
    }
  }
  if (mode === 'summary') {
    const o = [...counts.keys()].sort((a, b) => (a < b ? -1 : a > b ? 1 : 0))
      .map((k) => `${k} allowed=${counts.get(k).a} denied=${counts.get(k).d}`)
    o.push(`total allowed=${allowed} denied=${denied}`)
    return o.join('\n') + '\n'
  }
  return out.length ? out.join('\n') + '\n' : ''
}

try {
  process.stdout.write(run(readFileSync(0, 'utf8')))
} catch (e) {
  if (!(e instanceof Fail)) throw e
  process.stderr.write(`error: ${e.message}\n`)
  process.exit(2)
}
